// Infrastructure/LearningExamples/Session19BEmployeeRepository.cs
// Lab 2 of 3 - Observe internal Across Project Boundaries
namespace PinkMachine19.TimeClock.Infrastructure;

using PinkMachine19.TimeClock.Domain;

internal sealed class Session19BEmployeeRepository : IEmployeeRepository
{
    private readonly Employee _employee;

    public Session19BEmployeeRepository(Employee employee)
    {
        _employee = employee;
    }

    public Employee GetEmployeeById(int employeeId)
    {
        if (employeeId != _employee.EmployeeId)
        {
            throw new KeyNotFoundException($"Employee {employeeId} was not found.");
        }

        return _employee;
    }
}

public static class Session19BEmployeeRepositoryFactory
{
    public static IEmployeeRepository Create(Employee employee)
    {
        return new Session19BEmployeeRepository(employee);
    }
}

