// Lab 3 of 3 - Recognize protected and sealed Intent
public abstract class Session19BLabelBase
{
    public string Label { get; protected set; } = "";

    protected void SetLabel(string label)
    {
        Label = label.Trim();
    }
}

// Session19BEmployeeLabel.cs
public sealed class Session19BEmployeeLabel : Session19BLabelBase
{
    public void Rename(string name)
    {
        SetLabel(name);
    }
}

